ALTER TABLE public.courses ADD COLUMN status text NOT NULL DEFAULT 'publicado' CHECK(status IN ('rascunho','em_avaliacao','publicado','suspenso')), ADD COLUMN institution_id uuid REFERENCES public.institutions(id), ADD COLUMN scope_id uuid REFERENCES public.organization_scopes(id), ADD COLUMN media_approved boolean NOT NULL DEFAULT false;
UPDATE public.courses SET status=CASE WHEN published THEN 'publicado' ELSE 'rascunho' END;
ALTER TABLE public.courses ALTER COLUMN published SET DEFAULT false;
ALTER TABLE public.courses ALTER COLUMN status SET DEFAULT 'rascunho';
CREATE TABLE public.course_modules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),course_id uuid NOT NULL REFERENCES public.courses(id),title text NOT NULL,position integer NOT NULL DEFAULT 1,hours numeric NOT NULL DEFAULT 1,game jsonb NOT NULL DEFAULT '[]',legacy boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.course_modules TO anon,authenticated; GRANT ALL ON public.course_modules TO service_role;
ALTER TABLE public.course_modules ENABLE ROW LEVEL SECURITY;
CREATE POLICY modules_read ON public.course_modules FOR SELECT TO public USING(EXISTS(SELECT 1 FROM public.courses c WHERE c.id=course_id));
INSERT INTO public.course_modules(course_id,title,hours,legacy) SELECT id,title,hours,true FROM public.courses;
ALTER TABLE public.lessons ADD COLUMN module_id uuid REFERENCES public.course_modules(id),ADD COLUMN video_path text;
UPDATE public.lessons l SET module_id=m.id FROM public.course_modules m WHERE l.course_id=m.course_id;
CREATE TABLE public.module_assessments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),module_id uuid NOT NULL UNIQUE REFERENCES public.course_modules(id),questions jsonb NOT NULL,minimum_score numeric NOT NULL DEFAULT 70);
GRANT ALL ON public.module_assessments TO service_role;
ALTER TABLE public.module_assessments ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.assessment_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,profile_role public.profile_role NOT NULL,module_id uuid NOT NULL REFERENCES public.course_modules(id),score numeric NOT NULL,passed boolean NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.assessment_attempts TO authenticated; GRANT ALL ON public.assessment_attempts TO service_role;
ALTER TABLE public.assessment_attempts ENABLE ROW LEVEL SECURITY;
CREATE POLICY attempts_own ON public.assessment_attempts FOR SELECT TO authenticated USING(user_id=auth.uid() AND profile_role=public.current_profile_role() AND profile_role IN ('estudante','geral','colaborador'));
ALTER TABLE public.certificates ADD COLUMN module_id uuid REFERENCES public.course_modules(id), ADD COLUMN assessment_id uuid REFERENCES public.assessment_attempts(id),ADD COLUMN complementary boolean NOT NULL DEFAULT false,ADD COLUMN legacy boolean NOT NULL DEFAULT true;
CREATE TABLE public.student_verifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,institution_id uuid REFERENCES public.institutions(id),scope_id uuid REFERENCES public.organization_scopes(id),file_path text NOT NULL,status text NOT NULL DEFAULT 'pendente' CHECK(status IN ('pendente','validado','recusado','expirado')),submitted_at timestamptz NOT NULL DEFAULT now(),validated_by uuid,validated_at timestamptz,valid_until timestamptz,rejection_reason text);
GRANT SELECT ON public.student_verifications TO authenticated; GRANT ALL ON public.student_verifications TO service_role;
ALTER TABLE public.student_verifications ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.can_validate_student(_institution uuid,_scope uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND ((public.is_admin() AND public.current_profile_role() NOT IN ('professor','ies','empresa','colaborador')) OR (_institution IS NOT NULL AND public.organization_permission(_institution,'ies','validar_vinculos',_scope))) $$;
CREATE POLICY verifications_read ON public.student_verifications FOR SELECT TO authenticated USING((user_id=auth.uid() AND public.current_profile_role()='estudante') OR public.can_validate_student(institution_id,scope_id));
CREATE POLICY declaration_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='student-declarations' AND public.current_profile_role()='estudante' AND (storage.foldername(name))[1]=auth.uid()::text AND (storage.foldername(name))[2]='estudante');
CREATE POLICY declaration_validator_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='student-declarations' AND EXISTS(SELECT 1 FROM public.student_verifications v WHERE v.file_path=name AND public.can_validate_student(v.institution_id,v.scope_id)));
CREATE OR REPLACE FUNCTION public.submit_student_verification(_file text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE learner public.learner_profiles; result uuid; BEGIN IF auth.uid() IS NULL OR public.current_profile_role()<>'estudante' OR split_part(_file,'/',1)<>auth.uid()::text OR split_part(_file,'/',2)<>'estudante' THEN RAISE EXCEPTION 'Envio não autorizado'; END IF; IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='student-declarations' AND name=_file) THEN RAISE EXCEPTION 'Arquivo não encontrado'; END IF; SELECT * INTO learner FROM public.learner_profiles WHERE user_id=auth.uid() AND profile_role='estudante'; INSERT INTO public.student_verifications(user_id,institution_id,file_path) VALUES(auth.uid(),learner.institution_id,_file) RETURNING id INTO result; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.validate_student_verification(_id uuid,_approved boolean,_reason text,_until timestamptz) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v public.student_verifications; BEGIN SELECT * INTO v FROM public.student_verifications WHERE id=_id FOR UPDATE; IF NOT FOUND OR NOT public.can_validate_student(v.institution_id,v.scope_id) THEN RAISE EXCEPTION 'Validação não autorizada'; END IF; IF v.status<>'pendente' THEN RAISE EXCEPTION 'Este envio já foi analisado'; END IF; IF _approved AND (_until IS NULL OR _until<=now()) THEN RAISE EXCEPTION 'Informe validade futura'; END IF; IF NOT _approved AND length(trim(COALESCE(_reason,'')))<3 THEN RAISE EXCEPTION 'Informe o motivo da recusa'; END IF; UPDATE public.student_verifications SET status=CASE WHEN _approved THEN 'validado' ELSE 'recusado' END,validated_by=auth.uid(),validated_at=now(),valid_until=CASE WHEN _approved THEN _until ELSE NULL END,rejection_reason=CASE WHEN NOT _approved THEN _reason ELSE NULL END WHERE id=_id; INSERT INTO public.notifications(user_id,profile_role,title,body) VALUES(v.user_id,'estudante',CASE WHEN _approved THEN 'Vínculo validado' ELSE 'Declaração recusada' END,CASE WHEN _approved THEN 'Horas complementares liberadas até '||_until::date ELSE _reason||'. Você pode enviar nova declaração.' END); INSERT INTO public.activity_logs(user_id,organization_id,organization_type,scope_id,action,entity,meta) VALUES(auth.uid(),v.institution_id,CASE WHEN v.institution_id IS NOT NULL THEN 'ies' END,v.scope_id,'vinculo_validado','student_verifications',jsonb_build_object('verification_id',_id,'approved',_approved)); END $$;
CREATE OR REPLACE FUNCTION public.get_assessment(_module uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.module_assessments; BEGIN IF auth.uid() IS NULL OR public.current_profile_role() NOT IN ('estudante','geral','colaborador') THEN RAISE EXCEPTION 'Avaliação não autorizada'; END IF; IF NOT EXISTS(SELECT 1 FROM public.course_modules m JOIN public.courses c ON c.id=m.course_id WHERE m.id=_module AND c.status='publicado' AND c.published) THEN RAISE EXCEPTION 'Conteúdo indisponível'; END IF; SELECT * INTO a FROM public.module_assessments WHERE module_id=_module; IF NOT FOUND THEN RETURN NULL; END IF; RETURN jsonb_build_object('minimum_score',a.minimum_score,'questions',(SELECT jsonb_agg(q-'answer') FROM jsonb_array_elements(a.questions) q)); END $$;
CREATE OR REPLACE FUNCTION public.submit_assessment(_module uuid,_answers jsonb,_complementary boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.module_assessments; m public.course_modules; r public.profile_role; correct integer; total integer; score_value numeric; attempt uuid; completed_count integer; module_count integer; eligible boolean; result uuid; BEGIN r:=public.current_profile_role(); IF auth.uid() IS NULL OR r NOT IN ('estudante','geral','colaborador') THEN RAISE EXCEPTION 'Avaliação não autorizada'; END IF; SELECT cm.* INTO m FROM public.course_modules cm JOIN public.courses c ON c.id=cm.course_id WHERE cm.id=_module AND c.status='publicado' AND c.published; IF NOT FOUND THEN RAISE EXCEPTION 'Conteúdo indisponível'; END IF; SELECT * INTO a FROM public.module_assessments WHERE module_id=_module; IF NOT FOUND THEN RAISE EXCEPTION 'Avaliação ainda não cadastrada pelo autor'; END IF; total:=jsonb_array_length(a.questions); IF total=0 OR jsonb_typeof(_answers)<>'array' OR jsonb_array_length(_answers)<>total THEN RAISE EXCEPTION 'Responda todas as questões'; END IF; SELECT count(*) INTO correct FROM jsonb_array_elements(a.questions) WITH ORDINALITY q(value,n) WHERE (q.value->>'answer')::integer=(_answers->>((q.n-1)::integer))::integer; score_value:=100.0*correct/total;
INSERT INTO public.assessment_attempts(user_id,profile_role,module_id,score,passed) VALUES(auth.uid(),r,_module,score_value,score_value>=a.minimum_score) RETURNING id INTO attempt; IF score_value<a.minimum_score THEN RETURN jsonb_build_object('passed',false,'score',score_value,'certificate',false); END IF;
SELECT count(*) INTO module_count FROM public.course_modules WHERE course_id=m.course_id; SELECT count(DISTINCT x.module_id) INTO completed_count FROM public.assessment_attempts x JOIN public.course_modules cm ON cm.id=x.module_id WHERE cm.course_id=m.course_id AND x.user_id=auth.uid() AND x.profile_role=r AND x.passed;
INSERT INTO public.enrollments(user_id,course_id,profile_role,progress,completed_at) VALUES(auth.uid(),m.course_id,r,round(100.0*completed_count/module_count),CASE WHEN completed_count=module_count THEN now() END) ON CONFLICT(user_id,course_id,profile_role) DO UPDATE SET progress=EXCLUDED.progress,completed_at=EXCLUDED.completed_at;
eligible:=NOT _complementary OR (r='estudante' AND EXISTS(SELECT 1 FROM public.student_verifications v WHERE v.user_id=auth.uid() AND v.status='validado' AND v.valid_until>now())); IF NOT eligible THEN RETURN jsonb_build_object('passed',true,'score',score_value,'certificate',false,'requires_verification',true); END IF;
IF completed_count=module_count THEN INSERT INTO public.certificates(user_id,course_id,profile_role,module_id,assessment_id,hours,complementary,legacy) SELECT auth.uid(),m.course_id,r,m.id,attempt,sum(hours),_complementary,false FROM public.course_modules WHERE course_id=m.course_id ON CONFLICT(user_id,course_id,profile_role) DO NOTHING RETURNING id INTO result; END IF; RETURN jsonb_build_object('passed',true,'score',score_value,'certificate',completed_count=module_count,'requires_verification',false); END $$;
CREATE OR REPLACE FUNCTION public.guard_learning_evidence() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('authenticated','anon') THEN IF TG_TABLE_NAME='certificates' THEN RAISE EXCEPTION 'Certificação exige avaliação autorizada'; END IF; IF (TG_OP='INSERT' AND NEW.progress>=100) OR (TG_OP='UPDATE' AND NEW.progress>=100 AND OLD.progress<100) OR NEW.completed_at IS NOT NULL THEN RAISE EXCEPTION 'Conclusão exige aprovação na avaliação'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER certification_evidence BEFORE INSERT OR UPDATE ON public.certificates FOR EACH ROW EXECUTE FUNCTION public.guard_learning_evidence();
CREATE TRIGGER completion_evidence BEFORE INSERT OR UPDATE ON public.enrollments FOR EACH ROW EXECUTE FUNCTION public.guard_learning_evidence();
CREATE POLICY published_courses_guard ON public.courses AS RESTRICTIVE FOR SELECT TO public USING((published AND status='publicado') OR (instructor_id=auth.uid() AND public.current_profile_role()='professor') OR (institution_id IS NOT NULL AND public.organization_permission(institution_id,'ies','conteudo',scope_id)) OR public.is_admin());
CREATE POLICY course_owner_read ON public.courses FOR SELECT TO authenticated USING(instructor_id=auth.uid() OR public.organization_permission(institution_id,'ies','conteudo',scope_id));
CREATE OR REPLACE FUNCTION public.guard_course_publication() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE m public.course_modules; n integer; sum_minutes integer; valid boolean; BEGIN IF TG_OP='INSERT' AND current_user IN ('authenticated','anon') AND public.current_profile_role() NOT IN ('professor','ies') THEN RAISE EXCEPTION 'Publicação restrita a autores autorizados'; END IF; IF NEW.published AND (TG_OP='INSERT' OR NOT OLD.published OR NEW.status IS DISTINCT FROM OLD.status) THEN IF NOT NEW.media_approved THEN RAISE EXCEPTION 'Conteúdo precisa de revisão de formato, resolução e áudio'; END IF; IF NOT EXISTS(SELECT 1 FROM public.course_modules WHERE course_id=NEW.id) THEN RAISE EXCEPTION 'Cadastre os módulos'; END IF; FOR m IN SELECT * FROM public.course_modules WHERE course_id=NEW.id LOOP SELECT count(*),sum(duration_min),bool_and(duration_min=CASE WHEN (SELECT count(*) FROM public.lessons WHERE module_id=m.id)=4 THEN 15 ELSE 10 END) INTO n,sum_minutes,valid FROM public.lessons WHERE module_id=m.id; IF m.hours<1 OR sum_minutes<60 OR n NOT IN (4,6) OR NOT COALESCE(valid,false) THEN RAISE EXCEPTION 'Módulo exige quatro aulas de quinze minutos ou seis de dez'; END IF; IF jsonb_array_length(m.game)=0 OR NOT EXISTS(SELECT 1 FROM public.module_assessments WHERE module_id=m.id) THEN RAISE EXCEPTION 'Jogo e avaliação são obrigatórios'; END IF; END LOOP; END IF; IF current_user IN ('authenticated','anon') AND NEW.media_approved THEN RAISE EXCEPTION 'Aprovação de conteúdo exige revisão autorizada'; END IF; RETURN NEW; END $$;
CREATE TRIGGER publication_validation BEFORE INSERT OR UPDATE ON public.courses FOR EACH ROW EXECUTE FUNCTION public.guard_course_publication();
REVOKE ALL ON FUNCTION public.submit_student_verification(text),public.validate_student_verification(uuid,boolean,text,timestamptz),public.get_assessment(uuid),public.submit_assessment(uuid,jsonb,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.submit_student_verification(text),public.validate_student_verification(uuid,boolean,text,timestamptz),public.get_assessment(uuid),public.submit_assessment(uuid,jsonb,boolean) TO authenticated;